-- Ruang Kawan: Document Center register, templates, versions, requests, access, and audit.
insert into public.permissions(key,name,description) values
 ('documents.view','Lihat Document Center','Melihat dokumen sesuai scope dan klasifikasi.'),
 ('documents.create','Buat dokumen','Membuat draft, upload, dan registrasi link Drive.'),
 ('documents.review','Review dokumen','Memeriksa dokumen sebelum berlaku.'),
 ('documents.finalize','Finalisasi dokumen','Memberi nomor dan memberlakukan dokumen resmi.'),
 ('documents.manage','Kelola Document Center','Mengelola template, metadata, akses, arsip, dan void.')
on conflict(key) do update set name=excluded.name,description=excluded.description;
insert into public.role_permissions(role_id,permission_id)
select r.id,p.id from public.roles r join public.permissions p on
 r.key='system_admin' or (r.key='executive' and p.key in ('documents.view','documents.create','documents.review','documents.finalize'))
 or (r.key in ('project_lead','finance_manager','people_hr_manager','staff') and p.key in ('documents.view','documents.create'))
on conflict do nothing;

create table public.document_templates(
 id uuid primary key default extensions.gen_random_uuid(),template_code text not null unique,name text not null,document_type text not null,
 description text,owner_membership_id uuid not null references public.memberships(id),active_version integer not null default 1,
 status text not null default 'draft' check(status in ('draft','active','inactive','archived')),effective_date date,next_review_date date,
 drive_template_url text not null,required_fields jsonb not null default '[]'::jsonb check(jsonb_typeof(required_fields)='array'),
 created_by_membership_id uuid not null references public.memberships(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);
create table public.documents(
 id uuid primary key default extensions.gen_random_uuid(),document_id text not null unique,official_number text unique,external_number text,title text not null,
 document_type text not null,category text,description text,owner_membership_id uuid not null references public.memberships(id),department_id uuid references public.departments(id),
 source_module text,linked_record_id text,linked_record_name text,related_party text,template_id uuid references public.document_templates(id),
 active_version integer not null default 1,status text not null default 'draft' check(status in ('draft','review','effective','revised','superseded','archived','void')),
 classification text not null default 'internal' check(classification in ('public','internal','confidential','restricted')),tags text[] not null default '{}',
 valid_from date,expires_at date,next_review_date date,created_by_membership_id uuid not null references public.memberships(id),updated_by_membership_id uuid not null references public.memberships(id),
 deleted_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(expires_at is null or valid_from is null or expires_at>=valid_from)
);
create table public.document_versions(
 id uuid primary key default extensions.gen_random_uuid(),document_id uuid not null references public.documents(id) on delete cascade,version_number integer not null,
 file_name text not null,drive_file_url text not null,drive_folder_url text,file_type text,file_size bigint,source_kind text not null check(source_kind in ('generated','uploaded','existing_drive')),
 revision_reason text,revision_summary text,is_current boolean not null default true,immutable_at timestamptz,created_by_membership_id uuid not null references public.memberships(id),created_at timestamptz not null default now(),unique(document_id,version_number)
);
create unique index document_current_version_unique on public.document_versions(document_id) where is_current;
create table public.document_requests(
 id uuid primary key default extensions.gen_random_uuid(),request_code text not null unique,title text not null,request_type text not null check(request_type in ('new_document','provide_existing','revision','template_update','access_change','metadata_correction')),
 requester_membership_id uuid not null references public.memberships(id),assignee_membership_id uuid references public.memberships(id),document_id uuid references public.documents(id),source_module text,linked_record_id text,
 description text not null,priority text not null default 'medium' check(priority in ('low','medium','high','urgent')),target_date date,status text not null default 'requested' check(status in ('requested','in_progress','ready','completed','cancelled')),
 result_url text,resolution_note text,created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);
create table public.document_access_grants(id uuid primary key default extensions.gen_random_uuid(),document_id uuid not null references public.documents(id) on delete cascade,membership_id uuid not null references public.memberships(id),capability text not null check(capability in ('view','edit_draft','review','finalize','revise','archive','manage_access')),granted_by_membership_id uuid not null references public.memberships(id),created_at timestamptz not null default now(),unique(document_id,membership_id,capability));
create table public.document_events(id bigint generated always as identity primary key,document_id uuid references public.documents(id),request_id uuid references public.document_requests(id),actor_membership_id uuid not null references public.memberships(id),action text not null,before_data jsonb,after_data jsonb,reason text,created_at timestamptz not null default now());
create table public.document_number_sequences(document_type text not null,period_key text not null,last_number integer not null default 0,format_pattern text not null default '{SEQ}/{TYPE}/{YYYY}',primary key(document_type,period_key));
create sequence if not exists public.document_internal_seq start 1;
create sequence if not exists public.document_request_seq start 1;
create index documents_search_idx on public.documents(status,classification,document_type,updated_at desc) where deleted_at is null;
create index document_requests_owner_idx on public.document_requests(requester_membership_id,status,target_date);

create or replace function public.can_view_document(target uuid) returns boolean language sql stable security definer set search_path=public as $$
 select public.current_user_has_permission('documents.manage') or exists(select 1 from public.documents d where d.id=target and d.deleted_at is null and (d.owner_membership_id=public.current_membership_id() or d.classification in ('public','internal') or exists(select 1 from public.document_access_grants g where g.document_id=d.id and g.membership_id=public.current_membership_id() and g.capability='view') or (d.source_module='project' and d.linked_record_id~*'^[0-9a-f-]{36}$' and public.can_access_project(d.linked_record_id::uuid)))); $$;
create or replace function public.can_manage_document(target uuid,needed text) returns boolean language sql stable security definer set search_path=public as $$
 select public.current_user_has_permission('documents.manage') or exists(select 1 from public.documents d where d.id=target and d.owner_membership_id=public.current_membership_id() and needed in ('edit_draft','revise')) or exists(select 1 from public.document_access_grants g where g.document_id=target and g.membership_id=public.current_membership_id() and g.capability=needed); $$;

create or replace function public.document_center_workspace() returns jsonb language plpgsql stable security definer set search_path=public as $$
declare actor uuid:=public.current_membership_id();begin if actor is null or not public.current_user_has_permission('documents.view') then raise exception 'Akses Document Center diperlukan.' using errcode='42501';end if;
 return jsonb_build_object(
 'stats',jsonb_build_object('total',(select count(*) from public.documents d where d.deleted_at is null and public.can_view_document(d.id)),'active_templates',(select count(*) from public.document_templates where status='active'),'drafts',(select count(*) from public.documents d where d.status='draft' and public.can_view_document(d.id)),'needs_attention',(select count(*) from public.documents d where public.can_view_document(d.id) and (d.status='review' or d.expires_at<=current_date+30 or d.next_review_date<=current_date+30))),
 'templates',coalesce((select jsonb_agg(jsonb_build_object('id',t.id,'template_code',t.template_code,'name',t.name,'document_type',t.document_type,'description',t.description,'owner_membership_id',t.owner_membership_id,'owner_name',coalesce(m.full_name,m.email::text),'active_version',t.active_version,'status',t.status,'effective_date',t.effective_date,'next_review_date',t.next_review_date,'drive_template_url',t.drive_template_url,'required_fields',t.required_fields,'updated_at',t.updated_at) order by t.updated_at desc) from public.document_templates t join public.memberships m on m.id=t.owner_membership_id),'[]'::jsonb),
 'documents',coalesce((select jsonb_agg(jsonb_build_object('id',d.id,'document_id',d.document_id,'official_number',d.official_number,'external_number',d.external_number,'title',d.title,'document_type',d.document_type,'category',d.category,'owner_membership_id',d.owner_membership_id,'owner_name',coalesce(m.full_name,m.email::text),'source_module',d.source_module,'linked_record_id',d.linked_record_id,'linked_record_name',d.linked_record_name,'active_version',d.active_version,'status',d.status,'classification',d.classification,'tags',d.tags,'valid_from',d.valid_from,'expires_at',d.expires_at,'next_review_date',d.next_review_date,'updated_at',d.updated_at,'current_file',(select v.drive_file_url from public.document_versions v where v.document_id=d.id and v.is_current limit 1)) order by d.updated_at desc) from public.documents d join public.memberships m on m.id=d.owner_membership_id where d.deleted_at is null and public.can_view_document(d.id)),'[]'::jsonb),
 'requests',coalesce((select jsonb_agg(jsonb_build_object('id',r.id,'request_code',r.request_code,'title',r.title,'request_type',r.request_type,'requester_membership_id',r.requester_membership_id,'requester_name',coalesce(m.full_name,m.email::text),'assignee_membership_id',r.assignee_membership_id,'assignee_name',coalesce(a.full_name,a.email::text),'description',r.description,'priority',r.priority,'target_date',r.target_date,'status',r.status,'result_url',r.result_url,'updated_at',r.updated_at) order by r.updated_at desc) from public.document_requests r join public.memberships m on m.id=r.requester_membership_id left join public.memberships a on a.id=r.assignee_membership_id where r.requester_membership_id=actor or r.assignee_membership_id=actor or public.current_user_has_permission('documents.manage')),'[]'::jsonb),
 'members',case when public.current_user_has_permission('documents.manage') then coalesce((select jsonb_agg(jsonb_build_object('id',m.id,'name',coalesce(m.full_name,m.email::text)) order by coalesce(m.full_name,m.email::text)) from public.memberships m where m.status='active'),'[]'::jsonb) else '[]'::jsonb end);end;$$;

create or replace function public.save_document_template(template_id uuid,payload jsonb) returns uuid language plpgsql security definer set search_path=public as $$declare actor uuid:=public.current_membership_id();saved uuid;begin if not public.current_user_has_permission('documents.manage') then raise exception 'Akses pengelola template diperlukan.' using errcode='42501';end if;if template_id is null then insert into public.document_templates(template_code,name,document_type,description,owner_membership_id,status,effective_date,next_review_date,drive_template_url,required_fields,created_by_membership_id) values(upper(trim(payload->>'template_code')),trim(payload->>'name'),trim(payload->>'document_type'),nullif(payload->>'description',''),coalesce(nullif(payload->>'owner_membership_id','')::uuid,actor),coalesce(nullif(payload->>'status',''),'draft'),nullif(payload->>'effective_date','')::date,nullif(payload->>'next_review_date','')::date,payload->>'drive_template_url',coalesce(payload->'required_fields','[]'::jsonb),actor) returning id into saved;else update public.document_templates set name=trim(payload->>'name'),document_type=trim(payload->>'document_type'),description=nullif(payload->>'description',''),owner_membership_id=coalesce(nullif(payload->>'owner_membership_id','')::uuid,owner_membership_id),status=payload->>'status',effective_date=nullif(payload->>'effective_date','')::date,next_review_date=nullif(payload->>'next_review_date','')::date,drive_template_url=payload->>'drive_template_url',required_fields=coalesce(payload->'required_fields',required_fields),updated_at=now() where id=template_id returning id into saved;end if;return saved;end;$$;
create or replace function public.save_document(document_uuid uuid,payload jsonb) returns uuid language plpgsql security definer set search_path=public as $$declare actor uuid:=public.current_membership_id();saved uuid;doc_code text;before_row jsonb;begin if actor is null or not public.current_user_has_permission('documents.create') then raise exception 'Akses membuat dokumen diperlukan.' using errcode='42501';end if;if document_uuid is null then doc_code:='DOC-'||to_char(now(),'YYYYMM')||'-'||lpad(nextval('public.document_internal_seq')::text,5,'0');if exists(select 1 from public.documents where lower(title)=lower(trim(payload->>'title')) and coalesce(source_module,'')=coalesce(payload->>'source_module','') and coalesce(linked_record_id,'')=coalesce(payload->>'linked_record_id','') and deleted_at is null) then raise exception 'Dokumen serupa sudah terdaftar.';end if;insert into public.documents(document_id,external_number,title,document_type,category,description,owner_membership_id,source_module,linked_record_id,linked_record_name,related_party,template_id,status,classification,tags,valid_from,expires_at,next_review_date,created_by_membership_id,updated_by_membership_id) values(doc_code,nullif(payload->>'external_number',''),trim(payload->>'title'),trim(payload->>'document_type'),nullif(payload->>'category',''),nullif(payload->>'description',''),coalesce(nullif(payload->>'owner_membership_id','')::uuid,actor),nullif(payload->>'source_module',''),nullif(payload->>'linked_record_id',''),nullif(payload->>'linked_record_name',''),nullif(payload->>'related_party',''),nullif(payload->>'template_id','')::uuid,'draft',coalesce(nullif(payload->>'classification',''),'internal'),coalesce(array(select jsonb_array_elements_text(coalesce(payload->'tags','[]'::jsonb))),'{}'),nullif(payload->>'valid_from','')::date,nullif(payload->>'expires_at','')::date,nullif(payload->>'next_review_date','')::date,actor,actor) returning id into saved;if nullif(payload->>'drive_file_url','') is not null then insert into public.document_versions(document_id,version_number,file_name,drive_file_url,drive_folder_url,file_type,source_kind,revision_summary,created_by_membership_id) values(saved,1,coalesce(nullif(payload->>'file_name',''),trim(payload->>'title')),payload->>'drive_file_url',nullif(payload->>'drive_folder_url',''),nullif(payload->>'file_type',''),coalesce(nullif(payload->>'source_kind',''),'existing_drive'),'Initial registration',actor);end if;else if not public.can_manage_document(document_uuid,'edit_draft') then raise exception 'Dokumen tidak dapat diubah.' using errcode='42501';end if;select to_jsonb(d) into before_row from public.documents d where id=document_uuid;update public.documents set title=trim(payload->>'title'),document_type=trim(payload->>'document_type'),category=nullif(payload->>'category',''),description=nullif(payload->>'description',''),owner_membership_id=coalesce(nullif(payload->>'owner_membership_id','')::uuid,owner_membership_id),source_module=nullif(payload->>'source_module',''),linked_record_id=nullif(payload->>'linked_record_id',''),linked_record_name=nullif(payload->>'linked_record_name',''),classification=coalesce(nullif(payload->>'classification',''),classification),tags=coalesce(array(select jsonb_array_elements_text(coalesce(payload->'tags','[]'::jsonb))),tags),valid_from=nullif(payload->>'valid_from','')::date,expires_at=nullif(payload->>'expires_at','')::date,next_review_date=nullif(payload->>'next_review_date','')::date,updated_by_membership_id=actor,updated_at=now() where id=document_uuid returning id into saved;end if;insert into public.document_events(document_id,actor_membership_id,action,before_data,after_data) values(saved,actor,case when document_uuid is null then 'document.create' else 'document.update' end,before_row,payload);return saved;end;$$;
create or replace function public.transition_document(target uuid,new_status text,reason text default null) returns void language plpgsql security definer set search_path=public as $$declare actor uuid:=public.current_membership_id();d public.documents%rowtype;number_value text;seq integer;begin select * into d from public.documents where id=target and deleted_at is null;if d.id is null then raise exception 'Dokumen tidak ditemukan.';end if;if new_status='review' and not public.can_manage_document(target,'edit_draft') then raise exception 'Tidak diizinkan.' using errcode='42501';elsif new_status='effective' and not(public.current_user_has_permission('documents.finalize') or public.can_manage_document(target,'finalize')) then raise exception 'Izin finalisasi diperlukan.' using errcode='42501';elsif new_status in ('archived','void') and not public.current_user_has_permission('documents.manage') then raise exception 'Izin arsip/void diperlukan.' using errcode='42501';end if;if new_status='effective' and d.official_number is null then insert into public.document_number_sequences(document_type,period_key,last_number) values(d.document_type,to_char(current_date,'YYYY'),1) on conflict(document_type,period_key) do update set last_number=public.document_number_sequences.last_number+1 returning last_number into seq;number_value:=lpad(seq::text,4,'0')||'/'||upper(regexp_replace(d.document_type,'[^A-Za-z0-9]','','g'))||'/'||to_char(current_date,'YYYY');end if;update public.documents set status=new_status,official_number=coalesce(official_number,number_value),valid_from=case when new_status='effective' then coalesce(valid_from,current_date) else valid_from end,updated_by_membership_id=actor,updated_at=now() where id=target;insert into public.document_events(document_id,actor_membership_id,action,reason) values(target,actor,'document.status.'||new_status,reason);end;$$;
create or replace function public.create_document_revision(target uuid,payload jsonb) returns uuid language plpgsql security definer set search_path=public as $$declare actor uuid:=public.current_membership_id();d public.documents%rowtype;v integer;begin select * into d from public.documents where id=target;if d.status not in ('effective','revised') or not public.can_manage_document(target,'revise') then raise exception 'Revisi tidak diizinkan.' using errcode='42501';end if;v:=d.active_version+1;update public.document_versions set is_current=false,immutable_at=coalesce(immutable_at,now()) where document_id=target and is_current;insert into public.document_versions(document_id,version_number,file_name,drive_file_url,drive_folder_url,file_type,source_kind,revision_reason,revision_summary,created_by_membership_id) values(target,v,payload->>'file_name',payload->>'drive_file_url',nullif(payload->>'drive_folder_url',''),nullif(payload->>'file_type',''),coalesce(nullif(payload->>'source_kind',''),'existing_drive'),payload->>'revision_reason',payload->>'revision_summary',actor);update public.documents set active_version=v,status='revised',updated_by_membership_id=actor,updated_at=now() where id=target;insert into public.document_events(document_id,actor_membership_id,action,after_data,reason) values(target,actor,'document.revision',payload,payload->>'revision_reason');return target;end;$$;
create or replace function public.save_document_request(request_id uuid,payload jsonb) returns uuid language plpgsql security definer set search_path=public as $$declare actor uuid:=public.current_membership_id();saved uuid;begin if actor is null then raise exception 'Login diperlukan.';end if;if request_id is null then insert into public.document_requests(request_code,title,request_type,requester_membership_id,assignee_membership_id,document_id,source_module,linked_record_id,description,priority,target_date,status) values('REQ-'||to_char(now(),'YYYYMM')||'-'||lpad(nextval('public.document_request_seq')::text,5,'0'),trim(payload->>'title'),payload->>'request_type',actor,nullif(payload->>'assignee_membership_id','')::uuid,nullif(payload->>'document_id','')::uuid,nullif(payload->>'source_module',''),nullif(payload->>'linked_record_id',''),trim(payload->>'description'),coalesce(nullif(payload->>'priority',''),'medium'),nullif(payload->>'target_date','')::date,'requested') returning id into saved;else update public.document_requests set assignee_membership_id=coalesce(nullif(payload->>'assignee_membership_id','')::uuid,assignee_membership_id),status=coalesce(nullif(payload->>'status',''),status),result_url=nullif(payload->>'result_url',''),resolution_note=nullif(payload->>'resolution_note',''),updated_at=now() where id=request_id and (requester_membership_id=actor or assignee_membership_id=actor or public.current_user_has_permission('documents.manage')) returning id into saved;end if;return saved;end;$$;

alter table public.document_templates enable row level security;alter table public.documents enable row level security;alter table public.document_versions enable row level security;alter table public.document_requests enable row level security;alter table public.document_access_grants enable row level security;alter table public.document_events enable row level security;alter table public.document_number_sequences enable row level security;
revoke all on public.document_templates,public.documents,public.document_versions,public.document_requests,public.document_access_grants,public.document_events,public.document_number_sequences from anon,authenticated;
grant execute on function public.document_center_workspace(),public.save_document_template(uuid,jsonb),public.save_document(uuid,jsonb),public.transition_document(uuid,text,text),public.create_document_revision(uuid,jsonb),public.save_document_request(uuid,jsonb) to authenticated;
revoke execute on function public.document_center_workspace(),public.save_document_template(uuid,jsonb),public.save_document(uuid,jsonb),public.transition_document(uuid,text,text),public.create_document_revision(uuid,jsonb),public.save_document_request(uuid,jsonb) from anon,public;
